CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE normalized_email text; existing_user_id text;
BEGIN
 IF TG_RELID <> 'auth.users'::regclass OR TG_WHEN <> 'AFTER' OR TG_LEVEL <> 'ROW' OR TG_OP <> 'INSERT' THEN RAISE EXCEPTION 'This function is only permitted for normal Auth signup'; END IF;
 IF NEW.email IS NULL THEN RAISE EXCEPTION 'Email is required'; END IF;
 normalized_email := lower(trim(NEW.email));
 IF normalized_email !~ '^[a-z0-9]+([._+-][a-z0-9]+)*@virginia\.edu$' THEN RAISE EXCEPTION 'Only @virginia.edu email addresses are allowed'; END IF;
 SELECT id INTO existing_user_id FROM public."User" WHERE lower(email) = normalized_email LIMIT 1;
 IF existing_user_id IS NOT NULL AND existing_user_id <> NEW.id::text THEN RAISE EXCEPTION 'Email belongs to a different public user; manual identity review required'; END IF;
 INSERT INTO public."User" (id,email,role,"createdAt") VALUES (NEW.id::text,normalized_email,'STUDENT'::public."AppRole",COALESCE(NEW.created_at,now())) ON CONFLICT(id) DO UPDATE SET email=EXCLUDED.email;
 RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.outclass_annotation_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN RAISE EXCEPTION 'Annotations must be tombstoned with audit history'; END IF;
  IF TG_OP = 'UPDATE' THEN
    IF OLD."deletedAt" IS NOT NULL OR NEW.id <> OLD.id OR NEW."documentId" <> OLD."documentId" OR NEW."authorId" <> OLD."authorId" OR NEW."createdAt" <> OLD."createdAt" OR NEW.revision <> OLD.revision + 1 THEN RAISE EXCEPTION 'Annotation identity/revision is immutable'; END IF;
    IF NOT EXISTS(SELECT 1 FROM "InterviewAnnotationRevision" WHERE "annotationId"=OLD.id AND revision=OLD.revision) THEN RAISE EXCEPTION 'Annotation edit requires preserved history'; END IF;
  END IF;
  IF NOT EXISTS(SELECT 1 FROM "InterviewResumeDocument" d JOIN "Application" a ON a.id=d."applicationId" JOIN "ClubMember" m ON m.id=NEW."authorId" AND m."clubId"=a."clubId" WHERE d.id=NEW."documentId") THEN RAISE EXCEPTION 'Annotation club scope mismatch'; END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.outclass_application_notification()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$ BEGIN
  -- Canonical final publication inserts its immutable letter and availability notification.
  -- Keep legacy/unversioned events and all non-final application producers unchanged.
  IF NEW.status IN ('ACCEPTED','WAITLISTED','REJECTED') AND NEW."decisionVersion">0 THEN RETURN NEW; END IF;
  IF NEW.status='DRAFTING' OR NEW."submittedAt" IS NULL THEN RETURN NEW; END IF;
  IF TG_OP='UPDATE' AND NEW.status=OLD.status AND NEW."roundId"=OLD."roundId" THEN RETURN NEW; END IF;
  PERFORM outclass_notify(NEW."studentId",NEW."clubId",'application:'||NEW.id||':'||gen_random_uuid()::text,
    CASE WHEN NEW.status='INTERVIEWING' THEN 'INTERVIEW' ELSE 'APPLICATION' END,
    CASE WHEN NEW.status='INTERVIEWING' THEN 'You have an interview invitation' ELSE 'Application update' END,
    'Your application status is '||replace(lower(NEW.status::text),'_',' ')||'. Open your application for the latest details.',
    '/?workspace=student&view=tracker');
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.outclass_availability_override_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Availability override history is retained'; END IF;
 IF NOT EXISTS (SELECT 1 FROM "ClubMember" m JOIN "User" u ON u.id=m."userId" JOIN "Club" c ON c.id=m."clubId"
   WHERE m."clubId"=NEW."clubId" AND m."userId"=current_setting('outclass.override_actor',TRUE)
   AND m.status='ACTIVE' AND u."disabledAt" IS NULL AND c."suspendedAt" IS NULL
   AND 'PRESIDENT'=ANY(m."interviewOffices") AND (m."isOwner" OR 'interviews.manage'=ANY(m.permissions))) THEN
   RAISE EXCEPTION 'An authorized current president must explicitly confirm availability overrides';
 END IF;
 IF TG_OP='UPDATE' THEN
   IF OLD."revokedAt" IS NOT NULL OR NEW."revokedAt" IS NULL OR (to_jsonb(NEW)-'revokedAt') IS DISTINCT FROM (to_jsonb(OLD)-'revokedAt') THEN RAISE EXCEPTION 'Availability override history is immutable'; END IF;
 ELSIF NEW."createdBy" IS DISTINCT FROM current_setting('outclass.override_actor',TRUE) OR NEW."revokedAt" IS NOT NULL
   OR NOT EXISTS (SELECT 1 FROM "InterviewSlot" s JOIN "InterviewRoom" r ON r.id=s."roomId" WHERE s.id=NEW."slotId" AND s."clubId"=NEW."clubId" AND r."roundId"=NEW."roundId" AND s."startTime"=NEW."startTime" AND s."endTime"=NEW."endTime" AND r.duration=NEW.duration AND r.buffer=NEW.buffer) THEN
   RAISE EXCEPTION 'Availability override must match its exact current session';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.outclass_booking_notification()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$ DECLARE app "Application"; BEGIN
  SELECT * INTO app FROM "Application" WHERE id=COALESCE(NEW."applicationId",OLD."applicationId");
  IF app.id IS NULL THEN RETURN COALESCE(NEW,OLD); END IF;
  PERFORM outclass_notify(app."studentId",app."clubId",'booking:'||COALESCE(NEW.id,OLD.id)||':'||TG_OP||':'||gen_random_uuid()::text,'INTERVIEW',
    CASE WHEN TG_OP='DELETE' THEN 'Interview booking cancelled' WHEN TG_OP='INSERT' THEN 'Interview confirmed' ELSE 'Interview booking updated' END,
    'Open your application to review your current interview schedule.',CASE WHEN COALESCE(NEW."roundId",OLD."roundId") IS NULL THEN '/?workspace=student&view=tracker' ELSE '/interviews/book?clubId='||app."clubId"||'&roundId='||COALESCE(NEW."roundId",OLD."roundId") END);
  RETURN COALESCE(NEW,OLD);
END $function$

CREATE OR REPLACE FUNCTION public.outclass_collaboration_scope()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE s "InterviewCollaboration"; d "InterviewCollaboration"; m TEXT;
BEGIN
  IF TG_TABLE_NAME = 'InterviewCollaboration' THEN
    IF NOT EXISTS(SELECT 1 FROM "Application" a JOIN "PipelineRound" r ON r.id=NEW."roundId" AND r."clubId"=a."clubId" WHERE a.id=NEW."applicationId" AND a."clubId"=NEW."clubId") THEN RAISE EXCEPTION 'Collaboration scope mismatch'; END IF;
    IF TG_OP='UPDATE' AND (NEW.id<>OLD.id OR NEW."clubId"<>OLD."clubId" OR NEW."applicationId"<>OLD."applicationId" OR NEW."roundId"<>OLD."roundId" OR NEW."roomKey"<>OLD."roomKey" OR NEW.revision<>OLD.revision+1) THEN RAISE EXCEPTION 'Collaboration identity/revision mismatch'; END IF;
    IF NEW."selectedQuestionId" IS NOT NULL AND (NOT EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.questions) q WHERE q->>'id'=NEW."selectedQuestionId") OR NOT EXISTS(SELECT 1 FROM "ClubMember" WHERE id=NEW."selectedBy" AND "clubId"=NEW."clubId")) THEN RAISE EXCEPTION 'Invalid shared question'; END IF;
    IF TG_OP='UPDATE' AND EXISTS(SELECT 1 FROM jsonb_array_elements(OLD.questions) q WHERE NOT NEW.questions @> jsonb_build_array(q)) THEN RAISE EXCEPTION 'Shared question snapshots are immutable'; END IF;
    RETURN NEW;
  ELSIF TG_TABLE_NAME='InterviewPresence' THEN
    SELECT * INTO s FROM "InterviewCollaboration" WHERE id=NEW."sessionId"; m:=NEW."memberId";
  ELSIF TG_TABLE_NAME='InterviewMove' THEN
    SELECT * INTO s FROM "InterviewCollaboration" WHERE id=NEW."sourceId";
    SELECT * INTO d FROM "InterviewCollaboration" WHERE id=NEW."destinationId"; m:=NEW."memberId";
    IF s."clubId"<>d."clubId" OR s."roundId"<>d."roundId" THEN RAISE EXCEPTION 'Move scope mismatch'; END IF;
    IF TG_OP='UPDATE' AND (NEW.id<>OLD.id OR NEW."sourceId"<>OLD."sourceId" OR NEW."destinationId"<>OLD."destinationId" OR NEW."memberId"<>OLD."memberId" OR NEW.invited<>OLD.invited OR NEW."acceptedInvitationId" IS DISTINCT FROM OLD."acceptedInvitationId" OR NEW."createdAt"<>OLD."createdAt" OR NEW."expiresAt"<>OLD."expiresAt" OR OLD."confirmedAt" IS NOT NULL) THEN RAISE EXCEPTION 'Move receipt is immutable'; END IF;
  ELSE
    SELECT c.* INTO s FROM "InterviewMove" v JOIN "InterviewCollaboration" c ON c.id=v."sourceId" WHERE v.id=NEW."moveId"; m:=NEW."recipientId";
    IF TG_OP='UPDATE' AND (NEW.id<>OLD.id OR NEW."moveId"<>OLD."moveId" OR NEW."recipientId"<>OLD."recipientId" OR OLD."dismissedAt" IS NOT NULL) THEN RAISE EXCEPTION 'Invitation identity is immutable'; END IF;
  END IF;
  IF NOT EXISTS(SELECT 1 FROM "ClubMember" WHERE id=m AND "clubId"=s."clubId") THEN RAISE EXCEPTION 'Collaboration member scope mismatch'; END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.outclass_decision_state_revision()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF (NEW.status,NEW."roundId",NEW."decisionVersion",NEW."recruitmentCycleId") IS DISTINCT FROM (OLD.status,OLD."roundId",OLD."decisionVersion",OLD."recruitmentCycleId") THEN
  NEW."decisionStateRevision" := OLD."decisionStateRevision" + 1;
 ELSE NEW."decisionStateRevision" := OLD."decisionStateRevision";
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.outclass_disabled_room_approval()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW."disabledAt" IS NOT NULL AND OLD."disabledAt" IS NULL THEN
    UPDATE "InterviewPanelAssignment" SET "revokedAt"=NOW() WHERE "revokedAt" IS NULL AND "memberId" IN (SELECT id FROM "ClubMember" WHERE "userId"=NEW.id);
    UPDATE "InterviewPanelAssignment" SET "revokedAt"=NOW() WHERE "bookingManaged" AND "revokedAt" IS NULL AND "bookingId" IN
      (SELECT b.id FROM "InterviewBooking" b JOIN "InterviewSlot" slot ON slot.id=b."slotId" JOIN "InterviewPanelScheduleVersion" v ON v.id=slot."panelScheduleVersionId" WHERE v."publishedBy"=NEW.id);
    UPDATE "InterviewRoom" SET "approvedPanelMemberIds"=ARRAY[]::TEXT[],"panelApprovedBy"=NULL,"panelApprovalRevision"="panelApprovalRevision"+1
      WHERE "panelApprovedBy"=NEW.id OR "approvedPanelMemberIds" && ARRAY(SELECT id FROM "ClubMember" WHERE "userId"=NEW.id);
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.outclass_interview_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_TABLE_NAME IN ('InterviewResumeDocument','InterviewAnnotationRevision') THEN
    RAISE EXCEPTION 'Interview evidence is immutable';
  ELSIF TG_TABLE_NAME = 'InterviewRecord' THEN
    IF OLD."completedAt" IS NOT NULL THEN RAISE EXCEPTION 'Submitted interview is immutable'; END IF;
    IF TG_OP = 'UPDATE' AND (NEW.questions IS DISTINCT FROM OLD.questions OR NEW."applicationId" <> OLD."applicationId" OR NEW."roundId" <> OLD."roundId" OR NEW."interviewerId" <> OLD."interviewerId" OR NEW."anonymousReview" <> OLD."anonymousReview") THEN
      RAISE EXCEPTION 'Interview snapshot is immutable';
    END IF;
  ELSIF TG_TABLE_NAME = 'Evaluation' THEN
    IF OLD."submittedAt" IS NOT NULL OR EXISTS(SELECT 1 FROM "InterviewRecord" WHERE "evaluationId"=OLD.id AND "completedAt" IS NOT NULL) THEN
      RAISE EXCEPTION 'Submitted evaluation is immutable';
    END IF;
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.outclass_interview_scope_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE app_club TEXT; round_club TEXT; member_club TEXT;
BEGIN
  SELECT "clubId" INTO app_club FROM "Application" WHERE id=NEW."applicationId";
  SELECT "clubId" INTO round_club FROM "PipelineRound" WHERE id=NEW."roundId";
  IF app_club IS DISTINCT FROM round_club OR app_club IS NULL THEN RAISE EXCEPTION 'Interview club scope mismatch'; END IF;
  IF TG_TABLE_NAME = 'InterviewPanelAssignment' THEN
    SELECT "clubId" INTO member_club FROM "ClubMember" WHERE id=NEW."memberId";
    IF member_club IS DISTINCT FROM app_club THEN RAISE EXCEPTION 'Panel club scope mismatch'; END IF;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.outclass_interview_submission_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE e "Evaluation";
BEGIN
  IF TG_TABLE_NAME = 'Evaluation' THEN
    -- Apply new increment rules to new/changed scores, never rewrite historical values.
    IF TG_OP = 'INSERT' OR NEW.score IS DISTINCT FROM OLD.score OR (NEW."submittedAt" IS NOT NULL AND OLD."submittedAt" IS NULL) THEN
      IF NEW.score < 1 OR NEW.score > 10 OR NEW.score * 2 <> floor(NEW.score * 2) OR NEW.score = 'NaN'::float8 THEN RAISE EXCEPTION 'Score must be 1-10 in half points'; END IF;
    END IF;
    IF NEW."roundId" IS NOT NULL AND NOT EXISTS(SELECT 1 FROM "Application" a JOIN "PipelineRound" r ON r.id=NEW."roundId" AND r."clubId"=a."clubId" JOIN "ClubMember" m ON m.id=NEW."interviewerId" AND m."clubId"=a."clubId" WHERE a.id=NEW."applicationId") THEN RAISE EXCEPTION 'Evaluation scope mismatch'; END IF;
  ELSIF NEW."completedAt" IS NOT NULL THEN
    SELECT * INTO e FROM "Evaluation" WHERE id=NEW."evaluationId";
    IF e.id IS NULL OR e."submittedAt" IS NULL OR e."applicationId" <> NEW."applicationId" OR e."interviewerId" <> NEW."interviewerId" OR e."roundId" IS DISTINCT FROM NEW."roundId" THEN RAISE EXCEPTION 'Completion requires canonical submitted evaluation'; END IF;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.outclass_invalidate_room_approval()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.status<>'ACTIVE' OR NOT NEW."isOwner" AND OLD."isOwner" OR (NOT NEW."isOwner" AND NOT NEW.permissions @> ARRAY['applications.review','applicants.identify']::TEXT[]) THEN
    UPDATE "InterviewRoom" SET "approvedPanelMemberIds"=ARRAY[]::TEXT[],"panelApprovedBy"=NULL,"panelApprovalRevision"="panelApprovalRevision"+1
      WHERE "clubId"=NEW."clubId" AND (NEW.id=ANY("approvedPanelMemberIds") OR "panelApprovedBy"=NEW."userId");
  END IF;
  IF OLD."isOwner" AND (NOT NEW."isOwner" OR NEW.status<>'ACTIVE') THEN
    UPDATE "InterviewPanelAssignment" SET "revokedAt"=NOW() WHERE "bookingManaged" AND "revokedAt" IS NULL AND "bookingId" IN
      (SELECT b.id FROM "InterviewBooking" b JOIN "InterviewSlot" slot ON slot.id=b."slotId" JOIN "InterviewPanelScheduleVersion" v ON v.id=slot."panelScheduleVersionId" WHERE v."clubId"=NEW."clubId" AND v."publishedBy"=NEW."userId");
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.outclass_invitation_notification()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$ DECLARE recipient TEXT; BEGIN
  IF NEW."applicationId" IS NOT NULL THEN RETURN NEW; END IF;
  IF NEW.status<>'PENDING' OR NEW."expiresAt"<=CURRENT_TIMESTAMP THEN RETURN NEW; END IF;
  IF TG_OP='UPDATE' AND NEW.status=OLD.status THEN RETURN NEW; END IF;
  SELECT id INTO recipient FROM "User" WHERE lower(email)=lower(NEW.email) AND "disabledAt" IS NULL;
  IF recipient IS NOT NULL THEN
    PERFORM outclass_notify(recipient,NEW."clubId",'invitation:'||NEW.id,'INVITATION','You have a club invitation',
      'Review your invitation in organization settings. Joining is your choice.','/settings/organizations');
    -- Existing explicit invitation delivery remains authoritative; avoid a second email.
    UPDATE "NotificationEmailOutbox" SET status='SUPPRESSED' WHERE "notificationId" IN (SELECT id FROM "UserNotification" WHERE "userId"=recipient AND "eventKey"='invitation:'||NEW.id);
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.outclass_invitation_onboarding_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE recipient "SchoolIdentity"; actor "ClubMember"; permitted boolean;
BEGIN
  PERFORM id FROM "Club" WHERE id = NEW."clubId" FOR UPDATE;
  NEW.email := lower(btrim(NEW.email));
  IF NEW."schoolIdentityId" IS NULL AND TG_OP = 'INSERT' THEN
    SELECT "schoolId" INTO NEW."schoolId" FROM "Club" WHERE id = NEW."clubId";
  END IF;
  IF TG_OP = 'UPDATE' AND (
    NEW."clubId" <> OLD."clubId" OR NEW."schoolId" <> OLD."schoolId" OR
    NEW."schoolIdentityId" IS DISTINCT FROM OLD."schoolIdentityId" OR
    NEW."invitedBy" <> OLD."invitedBy" OR NEW."authoritySource" <> OLD."authoritySource" OR
    NEW.purpose <> OLD.purpose OR NEW."requestedRole" <> OLD."requestedRole" OR
    NEW.permissions <> OLD.permissions OR NEW.email <> lower(btrim(OLD.email))
  ) THEN RAISE EXCEPTION 'Invitation recipient and grant are immutable; revoke and reissue'; END IF;
  IF TG_OP = 'UPDATE' AND OLD.status <> 'PENDING' THEN
    IF NEW.status <> OLD.status OR NEW."acceptedAt" IS DISTINCT FROM OLD."acceptedAt" OR
       NEW."claimedUserId" IS DISTINCT FROM OLD."claimedUserId" OR NEW."claimedAt" IS DISTINCT FROM OLD."claimedAt" THEN
      RAISE EXCEPTION 'Terminal invitations cannot be reopened or reassigned';
    END IF;
    NEW.status := OLD.status;
  ELSE
    IF NEW."acceptedAt" IS NOT NULL THEN NEW.status := 'ACCEPTED';
    ELSIF NEW."declinedAt" IS NOT NULL THEN NEW.status := 'DECLINED';
    ELSIF NEW."revokedAt" IS NOT NULL THEN NEW.status := 'REVOKED';
    ELSIF NEW."expiresAt" <= CURRENT_TIMESTAMP THEN NEW.status := 'EXPIRED'; END IF;
  END IF;
  IF NEW.status = 'ACCEPTED' THEN NEW."claimedAt" := NEW."acceptedAt"; END IF;
  IF NEW.status = 'DECLINED' THEN NEW."declinedAt" := COALESCE(NEW."declinedAt", CURRENT_TIMESTAMP); END IF;
  IF NEW.status = 'REVOKED' THEN NEW."revokedAt" := COALESCE(NEW."revokedAt", CURRENT_TIMESTAMP); END IF;
  IF NEW.status = 'EXPIRED' THEN NEW."expiredAt" := COALESCE(NEW."expiredAt", NEW."expiresAt"); END IF;
  IF NEW."schoolIdentityId" IS NOT NULL THEN
    SELECT * INTO STRICT recipient FROM "SchoolIdentity" WHERE id = NEW."schoolIdentityId" AND "schoolId" = NEW."schoolId";
    IF TG_OP = 'INSERT' OR (TG_OP = 'UPDATE' AND OLD.status = 'PENDING' AND NEW.status = 'ACCEPTED') THEN
      IF NOT EXISTS (SELECT 1 FROM "User" WHERE id = NEW."invitedBy" AND "disabledAt" IS NULL) THEN
        RAISE EXCEPTION 'Inviter account unavailable';
      END IF;
      IF NEW."authoritySource" = 'PLATFORM_ADMIN' THEN
        permitted := EXISTS (SELECT 1 FROM "PlatformAdmin" WHERE "userId" = NEW."invitedBy" AND active);
      ELSE
        SELECT * INTO actor FROM "ClubMember" WHERE "clubId" = NEW."clubId" AND "userId" = NEW."invitedBy" AND status = 'ACTIVE';
        permitted := FOUND AND (actor."isOwner" OR (
          NEW."requestedRole" <> 'OWNER' AND
          ((NEW.purpose = 'MEMBERSHIP' AND NEW."requestedRole" = 'MEMBER' AND cardinality(NEW.permissions) = 0 AND 'members.manage' = ANY(actor.permissions)) OR
           ('leaders.manage' = ANY(actor.permissions) AND NEW.permissions <@ actor.permissions))
        ));
      END IF;
      IF NOT COALESCE(permitted, false) THEN RAISE EXCEPTION 'Invitation grant is not authorized'; END IF;
    END IF;
    IF NEW.status = 'ACCEPTED' THEN
      IF NEW."expiresAt" <= CURRENT_TIMESTAMP AND (TG_OP = 'INSERT' OR OLD.status = 'PENDING') THEN RAISE EXCEPTION 'Invitation expired'; END IF;
      IF recipient."userId" IS NULL OR recipient."verifiedAt" IS NULL OR NEW."claimedUserId" IS DISTINCT FROM recipient."userId" OR
         NOT EXISTS (SELECT 1 FROM "ClubMember" m JOIN "User" u ON u.id = m."userId"
           WHERE m."clubId" = NEW."clubId" AND m."userId" = NEW."claimedUserId" AND m.status = 'ACTIVE' AND u."disabledAt" IS NULL
           AND (NEW."requestedRole" <> 'OWNER' OR m."isOwner")) THEN
        RAISE EXCEPTION 'Invitation acceptance requires its verified identity and active membership';
      END IF;
    END IF;
  END IF;
  NEW."updatedAt" := CURRENT_TIMESTAMP;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.outclass_membership_onboarding_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM id FROM "Club" WHERE id = COALESCE(NEW."clubId", OLD."clubId") FOR UPDATE;
  IF TG_OP <> 'INSERT' AND OLD."isOwner" AND (TG_OP = 'DELETE' OR NOT NEW."isOwner" OR NEW.status <> 'ACTIVE') AND
    NOT EXISTS (SELECT 1 FROM "ClubMember" m JOIN "User" u ON u.id = m."userId"
      WHERE m."clubId" = OLD."clubId" AND m.id <> OLD.id AND m."isOwner" AND m.status = 'ACTIVE' AND u."disabledAt" IS NULL)
  THEN RAISE EXCEPTION 'Assign another active owner first'; END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  IF TG_OP = 'UPDATE' AND (NEW."clubId" <> OLD."clubId" OR NEW."userId" <> OLD."userId") THEN
    RAISE EXCEPTION 'Membership identity is immutable';
  END IF;
  IF NEW."isOwner" THEN
    -- A concurrent suspension must serialize with ownership promotion.
    PERFORM id FROM "User" WHERE id = NEW."userId" FOR UPDATE;
    IF NOT EXISTS (SELECT 1 FROM "User" WHERE id = NEW."userId" AND "disabledAt" IS NULL) THEN
      RAISE EXCEPTION 'Ownership requires an active account';
    END IF;
    NEW."accessRole" := 'OWNER';
  ELSIF NEW."accessRole" = 'OWNER' THEN
    IF TG_OP = 'UPDATE' AND OLD."isOwner" THEN NEW."accessRole" := 'MEMBER';
    ELSE RAISE EXCEPTION 'Owner role requires explicit ownership'; END IF;
  END IF;
  NEW."updatedAt" := CURRENT_TIMESTAMP;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.outclass_owner_account_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE owned record;
BEGIN
  IF OLD."disabledAt" IS NULL AND NEW."disabledAt" IS NOT NULL THEN
    FOR owned IN SELECT "clubId" FROM "ClubMember"
      WHERE "userId" = OLD.id AND "isOwner" AND status = 'ACTIVE' ORDER BY "clubId"
    LOOP
      PERFORM id FROM "Club" WHERE id = owned."clubId" FOR UPDATE;
      IF NOT EXISTS (
        SELECT 1 FROM "ClubMember" m JOIN "User" u ON u.id = m."userId"
        WHERE m."clubId" = owned."clubId" AND m."userId" <> OLD.id
          AND m."isOwner" AND m.status = 'ACTIVE' AND u."disabledAt" IS NULL
      ) THEN RAISE EXCEPTION 'Assign another active owner before suspending this account'; END IF;
    END LOOP;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.outclass_panel_publication_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE proposal "InterviewPanelProposal"; a JSONB;
BEGIN
  IF current_setting('outclass.panel_proposal_mode',TRUE)='unpublished' THEN RAISE EXCEPTION 'Unpublished previews cannot change publication'; END IF;
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Published panel history is immutable'; END IF;
  IF TG_OP='UPDATE' THEN
    IF NEW.status<>'SUPERSEDED' OR OLD.status<>'PUBLISHED' OR (to_jsonb(NEW)-'status') IS DISTINCT FROM (to_jsonb(OLD)-'status')
      OR NOT EXISTS (SELECT 1 FROM "InterviewPanelScheduleVersion" next WHERE next.id=current_setting('outclass.panel_publication_id',TRUE) AND next."clubId"=OLD."clubId" AND next."roundId"=OLD."roundId" AND next."previousVersion"=OLD.version) THEN RAISE EXCEPTION 'Published panel history is immutable'; END IF;
  ELSE
    IF current_setting('outclass.panel_publication_id',TRUE) IS DISTINCT FROM NEW.id OR NEW.status<>'PUBLISHED'
      OR NOT EXISTS (SELECT 1 FROM "PipelineRound" r WHERE r.id=NEW."roundId" AND r."clubId"=NEW."clubId" AND r."panelScheduleRevision"=NEW."previousVersion" AND r."archivedAt" IS NULL AND NOT r."anonymousReview")
      OR NOT EXISTS (SELECT 1 FROM "InterviewPanelProposal" p WHERE p.id=NEW."sourceProposalId" AND p."clubId"=NEW."clubId" AND p."roundId"=NEW."roundId" AND p.revision=NEW."sourceProposalRevision" AND p.status='READY_FOR_APPROVAL' AND p."approvalToken"=NEW."approvalToken" AND p."readyBy"=NEW."publishedBy" AND p."basePublishedVersion"=NEW."previousVersion")
      OR NOT EXISTS (SELECT 1 FROM "ClubMember" m JOIN "User" u ON u.id=m."userId" WHERE m."clubId"=NEW."clubId" AND m."userId"=NEW."publishedBy" AND m."isOwner" AND m.status='ACTIVE' AND u."disabledAt" IS NULL)
      THEN RAISE EXCEPTION 'Explicit current owner approval required for panel publication'; END IF;
    SELECT * INTO proposal FROM "InterviewPanelProposal" WHERE id=NEW."sourceProposalId";
    IF NOT NEW.document @> jsonb_build_object('sessions',proposal.document->'sessions','assignments',proposal.document->'assignments')
       OR EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.document->'assignments') item
         WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(proposal.document->'sessions') session WHERE session->>'id'=item->>'slotId')
         AND NOT proposal.document->'assignments' @> jsonb_build_array(item)) THEN
      RAISE EXCEPTION 'Published positions must match the exact reviewed draft';
    END IF;
    FOR a IN SELECT value FROM jsonb_array_elements(proposal.document->'assignments') LOOP
      IF NOT EXISTS(SELECT 1 FROM "ClubMember" m JOIN "User" u ON u.id=m."userId" JOIN "Club" c ON c.id=m."clubId"
        LEFT JOIN "InterviewRoundParticipation" participation ON participation."memberId"=m.id AND participation."roundId"=NEW."roundId" AND participation."clubId"=NEW."clubId"
        WHERE m.id=a->>'memberId' AND m."clubId"=NEW."clubId" AND m.status='ACTIVE' AND u."disabledAt" IS NULL AND c."suspendedAt" IS NULL
          AND (participation."confirmedAt" IS NOT NULL OR public.outclass_valid_availability_override(a->>'availabilityOverrideId',NEW."clubId",NEW."roundId",a->>'slotId',a->>'memberId'))
          AND COALESCE(participation."eligibilityOverride",m."interviewerEligible",m."accessRole"=ANY(c."interviewerRoles"))
          AND (m."isOwner" OR m.permissions @> ARRAY['applications.review','applicants.identify']::TEXT[])) THEN
        RAISE EXCEPTION 'Publication requires eligible confirmed identified interviewers';
      END IF;
    END LOOP;

  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.outclass_publication_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE e "Event"; BEGIN
 SELECT * INTO e FROM "Event" WHERE id=NEW."eventId" FOR UPDATE;
 IF TG_OP='UPDATE' AND ROW(NEW.category,NEW.contact,NEW."rsvpEnabled",NEW."rsvpRequired",NEW.capacity,NEW."rsvpDeadline",NEW.template,NEW."flyerId") IS DISTINCT FROM ROW(OLD.category,OLD.contact,OLD."rsvpEnabled",OLD."rsvpRequired",OLD.capacity,OLD."rsvpDeadline",OLD.template,OLD."flyerId") THEN
  NEW.status:='DRAFT'; NEW."approvedRevision":=NULL; NEW."publishedAt":=NULL;
 END IF;
 IF NEW."flyerId" IS NOT NULL AND NOT EXISTS(SELECT 1 FROM "EventFlyer" WHERE id=NEW."flyerId" AND "eventId"=NEW."eventId") THEN RAISE EXCEPTION 'Flyer belongs to another event'; END IF;
 IF NEW.status='PUBLISHED' AND (NOT e."isPublic" OR e.audience<>'RECRUITMENT' OR NEW."approvedRevision" IS DISTINCT FROM e.revision) THEN RAISE EXCEPTION 'Publication requires current approved public event revision'; END IF;
 IF NEW.capacity IS NOT NULL AND NEW.capacity<(SELECT count(*) FROM "EventRsvp" WHERE "eventId"=NEW."eventId") THEN RAISE EXCEPTION 'Capacity is below existing RSVPs'; END IF;
 IF NEW.status IN ('PENDING','PUBLISHED') AND NEW."rsvpDeadline" IS NOT NULL AND NEW."rsvpDeadline">e.date THEN RAISE EXCEPTION 'RSVP deadline must not follow event start'; END IF;
 RETURN NEW;
END $function$

