CREATE OR REPLACE FUNCTION public.outclass_revoke_interview_grants()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.status <> 'ACTIVE' THEN
    NEW."interviewOffices" := ARRAY[]::TEXT[];
  END IF;
  IF NEW.status <> 'ACTIVE' OR (NOT NEW."isOwner" AND NOT (NEW.permissions @> ARRAY['applications.review','applicants.identify']::TEXT[])) THEN
    UPDATE "InterviewPanelAssignment" SET "revokedAt"=CURRENT_TIMESTAMP WHERE "memberId"=NEW.id AND "revokedAt" IS NULL;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.outclass_room_booking_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  target_slot "InterviewSlot"%ROWTYPE;
  target_room "InterviewRoom"%ROWTYPE;
  applicant "Application"%ROWTYPE;
BEGIN
  SELECT * INTO applicant FROM "Application" WHERE id = NEW."applicationId";
  IF NOT FOUND THEN RAISE EXCEPTION 'Application unavailable'; END IF;
  PERFORM id FROM "User" WHERE id = applicant."studentId" FOR UPDATE;
  SELECT * INTO target_slot FROM "InterviewSlot" WHERE id = NEW."slotId" FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Slot unavailable'; END IF;
  -- Keep pre-existing standalone slots compatible with their original workflow.
  IF target_slot."roomId" IS NULL THEN RETURN NEW; END IF;
  SELECT * INTO target_room FROM "InterviewRoom" WHERE id = target_slot."roomId";
  IF target_slot."clubId" <> applicant."clubId" OR target_room."clubId" <> applicant."clubId"
    OR target_room."roundId" <> applicant."roundId" OR applicant.status <> 'INTERVIEWING' THEN
    RAISE EXCEPTION 'An invitation to this club and round is required';
  END IF;
  IF NOT target_room."isOpen" OR target_slot."startTime" <= CURRENT_TIMESTAMP THEN
    RAISE EXCEPTION 'This slot is no longer available';
  END IF;
  NEW."roundId" := target_room."roundId";
  IF (SELECT COUNT(*) FROM "InterviewBooking" WHERE "slotId" = NEW."slotId" AND id <> NEW.id) >= target_slot.capacity THEN
    RAISE EXCEPTION 'Interview capacity reached';
  END IF;
  IF EXISTS (
    SELECT 1 FROM "InterviewBooking" b JOIN "InterviewSlot" s ON s.id = b."slotId"
      JOIN "Application" a ON a.id = b."applicationId"
    WHERE a."studentId" = applicant."studentId" AND b.id <> NEW.id
      AND s."startTime" < target_slot."endTime" AND s."endTime" > target_slot."startTime"
  ) THEN RAISE EXCEPTION 'You already have an interview at this time'; END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.outclass_room_panel_change()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW."panelMemberIds" IS DISTINCT FROM OLD."panelMemberIds" OR (OLD."isOpen" AND NOT NEW."isOpen") THEN
    NEW."approvedPanelMemberIds" := ARRAY[]::TEXT[]; NEW."panelApprovedBy" := NULL;
    NEW."panelApprovalRevision" := OLD."panelApprovalRevision" + 1;
  END IF;
  IF NEW."approvedPanelMemberIds" IS DISTINCT FROM OLD."approvedPanelMemberIds" OR NEW."panelApprovedBy" IS DISTINCT FROM OLD."panelApprovedBy" OR NEW."panelMemberIds" IS DISTINCT FROM OLD."panelMemberIds" OR NEW."isOpen" IS DISTINCT FROM OLD."isOpen" THEN
    UPDATE "InterviewPanelAssignment" SET "revokedAt"=NOW() WHERE "bookingManaged" AND "revokedAt" IS NULL AND "bookingId" IN
      (SELECT b.id FROM "InterviewBooking" b JOIN "InterviewSlot" s ON s.id=b."slotId" WHERE s."roomId"=OLD.id AND (NEW."isOpen" IS DISTINCT FROM OLD."isOpen" OR s."panelScheduleVersionId" IS NULL));
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.outclass_roster_import_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM id FROM "Club" WHERE id = NEW."clubId" FOR UPDATE;
  IF TG_OP = 'INSERT' AND NOT EXISTS (
    SELECT 1 FROM "ClubMember" m JOIN "User" u ON u.id = m."userId"
    WHERE m."clubId" = NEW."clubId" AND m."userId" = NEW."uploadedById" AND m.status = 'ACTIVE' AND u."disabledAt" IS NULL
      AND (m."isOwner" OR 'members.manage' = ANY(m.permissions))
  ) THEN RAISE EXCEPTION 'Roster upload requires member-management access'; END IF;
  IF TG_OP = 'UPDATE' AND (NEW."clubId", NEW."uploadedById", NEW.filename, NEW."fileHash", NEW."idempotencyKey", NEW."rowCount") IS DISTINCT FROM
    (OLD."clubId", OLD."uploadedById", OLD.filename, OLD."fileHash", OLD."idempotencyKey", OLD."rowCount") THEN
    RAISE EXCEPTION 'Roster upload provenance is immutable';
  END IF;
  NEW."updatedAt" := CURRENT_TIMESTAMP;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.outclass_roster_row_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'UPDATE' AND (NEW."importId", NEW."clubId", NEW."rowNumber", NEW.input) IS DISTINCT FROM
    (OLD."importId", OLD."clubId", OLD."rowNumber", OLD.input) THEN
    RAISE EXCEPTION 'Original roster rows are immutable';
  END IF;
  IF NEW."schoolIdentityId" IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM "SchoolIdentity" s JOIN "Club" c ON c."schoolId" = s."schoolId"
    WHERE s.id = NEW."schoolIdentityId" AND c.id = NEW."clubId"
  ) THEN RAISE EXCEPTION 'Roster identity belongs to another school'; END IF;
