  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.outclass_rsvp_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE e "Event"; p "EventPublication"; BEGIN
 SELECT * INTO e FROM "Event" WHERE id=NEW."eventId" FOR UPDATE;
 SELECT * INTO p FROM "EventPublication" WHERE "eventId"=NEW."eventId";
 IF p.status IS DISTINCT FROM 'PUBLISHED' OR p."approvedRevision" IS DISTINCT FROM e.revision OR NOT e."isPublic" OR NOT p."rsvpEnabled" OR e.date<=CURRENT_TIMESTAMP OR (p."rsvpDeadline" IS NOT NULL AND p."rsvpDeadline"<=CURRENT_TIMESTAMP) THEN RAISE EXCEPTION 'RSVP is unavailable'; END IF;
 IF p.capacity IS NOT NULL AND (SELECT count(*) FROM "EventRsvp" WHERE "eventId"=NEW."eventId")>=p.capacity THEN RAISE EXCEPTION 'Event is full'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.outclass_scholar_status_valid(v jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE choices JSONB; item JSONB;
BEGIN
  IF v IS NULL THEN RETURN TRUE; END IF;
  IF jsonb_typeof(v) <> 'object' THEN RETURN FALSE; END IF;
  choices := v->'selections';
  IF choices IS NULL OR jsonb_typeof(choices) <> 'array' THEN RETURN FALSE; END IF;
  IF jsonb_array_length(choices) NOT BETWEEN 1 AND 9 THEN RETURN FALSE; END IF;
  IF (SELECT count(DISTINCT x) FROM jsonb_array_elements(choices) x) <> jsonb_array_length(choices) THEN RETURN FALSE; END IF;
  FOR item IN SELECT * FROM jsonb_array_elements(choices) LOOP
    IF NOT item <@ '["JEFFERSON","WALENTAS","ECHOLS","RODMAN","NOT_APPLICABLE","OTHER","COLLEGE_SCIENCE","MILLER_ARTS","CORE"]'::jsonb THEN RETURN FALSE; END IF;
  END LOOP;
  IF choices ? 'NOT_APPLICABLE' AND jsonb_array_length(choices) <> 1 THEN RETURN FALSE; END IF;
  IF jsonb_typeof(v->'other') IS DISTINCT FROM 'string' OR length(v->>'other') > 200 THEN RETURN FALSE; END IF;
  RETURN CASE WHEN choices ? 'OTHER' THEN length(btrim(v->>'other')) > 0 ELSE v->>'other' = '' END;
END $function$

CREATE OR REPLACE FUNCTION public.outclass_school_identity_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE config "SchoolIdentifierType";
BEGIN
  SELECT * INTO STRICT config FROM "SchoolIdentifierType" WHERE id = NEW."identifierTypeId" AND "schoolId" = NEW."schoolId";
  NEW."normalizedIdentifier" := CASE WHEN config.normalization = 'TRIM_LOWERCASE' THEN lower(btrim(NEW.identifier)) ELSE btrim(NEW.identifier) END;
  IF length(NEW."normalizedIdentifier") NOT BETWEEN 1 AND 128 OR NEW."normalizedIdentifier" ~ '[[:cntrl:]]' OR
     (config."validationRegex" IS NOT NULL AND NEW."normalizedIdentifier" !~ config."validationRegex") THEN
    RAISE EXCEPTION 'Invalid school identifier';
  END IF;
  IF TG_OP = 'UPDATE' AND (
    NEW."schoolId" <> OLD."schoolId" OR NEW."identifierTypeId" <> OLD."identifierTypeId" OR
    NEW."normalizedIdentifier" <> OLD."normalizedIdentifier" OR
    (OLD."userId" IS NOT NULL AND NEW."userId" IS DISTINCT FROM OLD."userId")
  ) THEN RAISE EXCEPTION 'School identity keys and verified ownership are immutable'; END IF;
  NEW."updatedAt" := CURRENT_TIMESTAMP;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.outclass_task_notification()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$ DECLARE task "ClubTask"; label TEXT; BEGIN
  SELECT * INTO task FROM "ClubTask" WHERE id=NEW."taskId";
  IF task.kind<>'TASK' OR task.status='DRAFT' OR NEW."memberId" IS NULL OR NOT EXISTS(SELECT 1 FROM "ClubMember" WHERE id=NEW."memberId" AND status='ACTIVE') THEN RETURN NEW; END IF;
  IF TG_OP='INSERT' THEN label='New task';
  ELSIF NEW."revisionRequestedAt" IS DISTINCT FROM OLD."revisionRequestedAt" AND NEW."revisionRequestedAt" IS NOT NULL THEN label='Revisions requested';
  ELSIF NEW."reviewedAt" IS DISTINCT FROM OLD."reviewedAt" AND NEW."reviewedAt" IS NOT NULL THEN label='Submission reviewed';
  ELSE RETURN NEW; END IF;
  PERFORM outclass_notify(NEW."userId",task."clubId",'task:'||NEW.id||':'||gen_random_uuid()::text,'TASK',label||': '||task.title,
    'Open your task for instructions and feedback.','/club/'||task."clubId"||'/workspace?section=tasks&taskView=mine&taskId='||task.id);
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.outclass_valid_availability(schedule jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE day JSONB; exception RECORD;
BEGIN
  IF jsonb_typeof(schedule) IS DISTINCT FROM 'object'
     OR (SELECT count(*) FROM jsonb_object_keys(schedule)) <> 4
     OR jsonb_typeof(schedule->'timezone') IS DISTINCT FROM 'string'
     OR NOT EXISTS(SELECT 1 FROM pg_timezone_names WHERE name=schedule->>'timezone')
     OR jsonb_typeof(schedule->'weeklySubmitted') IS DISTINCT FROM 'boolean'
     OR jsonb_typeof(schedule->'weekly') IS DISTINCT FROM 'array' OR jsonb_array_length(schedule->'weekly') <> 7
     OR jsonb_typeof(schedule->'exceptions') IS DISTINCT FROM 'object'
     OR (SELECT count(*) FROM jsonb_object_keys(schedule->'exceptions')) > 400 THEN RETURN FALSE; END IF;
  FOR day IN SELECT value FROM jsonb_array_elements(schedule->'weekly') LOOP
    IF NOT public.outclass_valid_availability_ranges(day) THEN RETURN FALSE; END IF;
  END LOOP;
  FOR exception IN SELECT key, value FROM jsonb_each(schedule->'exceptions') LOOP
    IF exception.key !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' OR exception.key < '1900-01-01' OR exception.key > '2200-12-31'
       OR to_char(exception.key::DATE, 'YYYY-MM-DD') <> exception.key
       OR NOT public.outclass_valid_availability_ranges(exception.value) THEN RETURN FALSE; END IF;
  END LOOP;
  RETURN TRUE;
EXCEPTION WHEN OTHERS THEN RETURN FALSE;
END $function$

CREATE OR REPLACE FUNCTION public.outclass_valid_availability_ranges(ranges jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE r JSONB; a INTEGER; b INTEGER; previous_end INTEGER := -1;
BEGIN
  IF jsonb_typeof(ranges) IS DISTINCT FROM 'array' OR jsonb_array_length(ranges) > 48 THEN RETURN FALSE; END IF;
  FOR r IN SELECT value FROM jsonb_array_elements(ranges) LOOP
    IF jsonb_typeof(r) IS DISTINCT FROM 'array' OR jsonb_array_length(r) <> 2
       OR jsonb_typeof(r->0) IS DISTINCT FROM 'number' OR jsonb_typeof(r->1) IS DISTINCT FROM 'number'
       OR r->>0 !~ '^[0-9]+$' OR r->>1 !~ '^[0-9]+$' THEN RETURN FALSE; END IF;
    a := (r->>0)::INTEGER; b := (r->>1)::INTEGER;
    IF a < 0 OR b > 1440 OR a >= b OR a % 15 <> 0 OR b % 15 <> 0 OR a < previous_end THEN RETURN FALSE; END IF;
    previous_end := b;
  END LOOP;
  RETURN TRUE;
EXCEPTION WHEN OTHERS THEN RETURN FALSE;
END $function$

CREATE OR REPLACE FUNCTION public.outclass_validate_changed_gpa()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP = 'UPDATE' AND NEW.gpa IS NOT DISTINCT FROM OLD.gpa THEN RETURN NEW; END IF;
 IF NEW.gpa IS NOT NULL AND NOT (NEW.gpa >= 0 AND NEW.gpa <= 4 AND abs(NEW.gpa * 1000 - round(NEW.gpa * 1000)) < 0.00000001) THEN
  RAISE EXCEPTION 'GPA must be 0–4 with at most three decimal places' USING ERRCODE = '23514';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.outclass_validate_panel_proposal()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE s JSONB; a JSONB; prior JSONB := '{}'::JSONB;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    prior := OLD.document;
    IF (NEW.id, NEW."clubId", NEW."roundId", NEW."createdBy", NEW."createdAt") IS DISTINCT FROM
       (OLD.id, OLD."clubId", OLD."roundId", OLD."createdBy", OLD."createdAt") OR NEW.revision <> OLD.revision + 1 THEN
      RAISE EXCEPTION 'Proposal identity is immutable and revision must advance once';
    END IF;
  END IF;
  FOR s IN SELECT value FROM jsonb_array_elements(NEW.document->'sessions') LOOP
    IF NOT EXISTS (SELECT 1 FROM "InterviewSlot" slot JOIN "InterviewRoom" room ON room.id=slot."roomId"
      WHERE slot.id=s->>'id' AND room.id=s->>'roomId' AND room."clubId"=NEW."clubId" AND room."roundId"=NEW."roundId")
      AND NOT COALESCE(prior->'sessions' @> jsonb_build_array(s), FALSE) THEN
      RAISE EXCEPTION 'Proposal session must belong to this round';
    END IF;
  END LOOP;
  FOR a IN SELECT value FROM jsonb_array_elements(NEW.document->'assignments') LOOP
    IF NOT EXISTS (SELECT 1 FROM jsonb_array_elements(NEW.document->'sessions') snapshot WHERE snapshot->>'id'=a->>'slotId') THEN
      RAISE EXCEPTION 'Proposal assignment must reference a snapshot session';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM "ClubMember" m WHERE m.id=a->>'memberId' AND m."clubId"=NEW."clubId")
      AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(prior->'assignments','[]'::JSONB)) olda
        WHERE olda->>'slotId'=a->>'slotId' AND olda->>'memberId'=a->>'memberId') THEN
      RAISE EXCEPTION 'Proposal interviewer must belong to this club';
    END IF;
  END LOOP;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.voting_display_snapshot_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF (OLD."startedAt" IS NOT NULL OR OLD."joinOpenedAt" IS NOT NULL) AND NEW."displayConfig" IS DISTINCT FROM OLD."displayConfig" THEN
    RAISE EXCEPTION 'Voting display snapshot is locked';
  END IF;
  IF NEW."activeApplicationId" IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM "VotingPassCandidate" c WHERE c."sessionId"=NEW.id AND c."passNumber"=NEW."currentPass" AND c."applicationId"=NEW."activeApplicationId"
  ) THEN RAISE EXCEPTION 'Active candidate must belong to the current pass'; END IF;
  RETURN NEW;
END $function$
